class NumericEntityUnescaper:
    HEX_BASE = 16
    DECIMAL_BASE = 10

    def __init__(self):
        self._hex_chars = set('0123456789abcdefABCDEF')

    def replace(self, string):
        out = []
        pos = 0
        length = len(string)

        while pos < length - 2:
            if self._is_numeric_entity_start(string, pos):
                escaped_char, new_pos = self._decode_numeric_entity(string, pos, length)
                if escaped_char is not None:
                    out.append(escaped_char)
                    pos = new_pos
                    continue

            out.append(string[pos])
            pos += 1

        return ''.join(out)

    def _is_numeric_entity_start(self, string, pos):
        return pos + 2 < len(string) and string[pos] == '&' and string[pos + 1] == '#'

    def _decode_numeric_entity(self, string, pos, length):
        start = pos + 2
        is_hex = False

        if start < length and string[start] in ('x', 'X'):
            start += 1
            is_hex = True

        if start >= length:
            return None, pos

        end = start
        while end < length and self._is_hex_char(string[end], is_hex):
            end += 1

        if end < length and string[end] == ';':
            entity_str = string[start:end]
            if self._is_valid_entity_string(entity_str, is_hex):
                try:
                    entity_value = int(entity_str, self._get_base(is_hex))
                    return chr(entity_value), end + 1
                except ValueError:
                    return None, pos

        return None, pos

    def _is_hex_char(self, char, is_hex):
        if is_hex:
            return char in self._hex_chars
        return char.isdigit()

    def _is_valid_entity_string(self, entity_str, is_hex):
        if not entity_str:
            return False
        if is_hex:
            return all(c in self._hex_chars for c in entity_str)
        return entity_str.isdigit()

    @staticmethod
    def _get_base(is_hex):
        return 16 if is_hex else 10

    @staticmethod
    def is_hex_char(char):
        return char.isdigit() or ('a' <= char.lower() <= 'f')
